using System;
using System.Collections.Generic;
using Rubikos.Core;
using Rubikos.View;
using UnityEngine;

namespace Rubikos.Game
{
    /// <summary>
    /// Plays sound effects. By default the sounds are generated by SoundSynth (no audio files needed).
    /// Drop your own AudioClips into the optional fields to replace them.
    /// </summary>
    [RequireComponent(typeof(AudioSource))]
    public class AudioPlayer : MonoBehaviour
    {
        private const string MutedKey = "Rubikos.Muted";

        [SerializeField] private GameController game;
        [SerializeField] private MoveQueue moveQueue;
        [SerializeField, Range(0f, 1f)] private float volume = 0.6f;

        [Header("Optional: your own sounds. Leave empty to use the built-in ones.")]
        [SerializeField] private AudioClip moveClip;
        [SerializeField] private AudioClip solvedClip;
        [SerializeField] private AudioClip rejectedClip;

        private readonly List<AudioClip> generatedClips = new List<AudioClip>();
        private AudioSource source;
        private float lastMoveSoundTime = -1f;

        public bool Muted { get; private set; }

        /// <summary>Raised when the sound is switched on or off.</summary>
        public event Action MuteChanged;

        private void Awake()
        {
            source = GetComponent<AudioSource>();
            source.playOnAwake = false;
            source.spatialBlend = 0f; // 2D sound: same volume wherever the camera is

            if (moveClip == null)     moveClip = MakeClip("Move", SoundSynth.Thock());
            if (solvedClip == null)   solvedClip = MakeClip("Solved", SoundSynth.Chime());
            if (rejectedClip == null) rejectedClip = MakeClip("Rejected", SoundSynth.Buzz());

            Muted = PlayerPrefs.GetInt(MutedKey, 0) == 1;
        }

        private void OnEnable()
        {
            moveQueue.MoveFinished += OnMoveFinished;
            game.Solved += OnSolved;
            game.MoveRejected += OnRejected;
        }

        private void OnDisable()
        {
            moveQueue.MoveFinished -= OnMoveFinished;
            game.Solved -= OnSolved;
            game.MoveRejected -= OnRejected;
        }

        private void OnDestroy()
        {
            foreach (AudioClip clip in generatedClips)
                if (clip != null) Destroy(clip);
        }

        public void ToggleMute() => SetMuted(!Muted);

        public void SetMuted(bool muted)
        {
            Muted = muted;
            PlayerPrefs.SetInt(MutedKey, muted ? 1 : 0);
            PlayerPrefs.Save();
            MuteChanged?.Invoke();
        }

        // Played when a turn animation FINISHES, so a scramble makes a quick rattle instead of one big bang.
        private void OnMoveFinished(Move move)
        {
            if (Time.unscaledTime - lastMoveSoundTime < 0.04f) return; // never stack sounds too tightly
            lastMoveSoundTime = Time.unscaledTime;

            source.pitch = UnityEngine.Random.Range(0.92f, 1.08f); // a little variety sounds more natural
            Play(moveClip);
        }

        private void OnSolved()
        {
            source.pitch = 1f;
            Play(solvedClip);
        }

        private void OnRejected(Move move)
        {
            source.pitch = 1f;
            Play(rejectedClip);
        }

        private void Play(AudioClip clip)
        {
            if (Muted || clip == null) return;
            source.PlayOneShot(clip, volume);
        }

        private AudioClip MakeClip(string clipName, float[] samples)
        {
            AudioClip clip = AudioClip.Create(clipName, samples.Length, 1, SoundSynth.SampleRate, false);
            clip.SetData(samples, 0);
            generatedClips.Add(clip);
            return clip;
        }
    }
}